import { test, expect } from '@playwright/test';

test.describe('Multiple Concurrent API Calls - Data Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display data after multiple concurrent API calls resolve', async ({ page }) => {
    // Setup intercepts for API calls
    await page.route('**/api/data/items', (route) => {
      route.continue();
    });
    await page.route('**/api/data/stats', (route) => {
      route.continue();
    });

    // Get initial data
    const itemsList = page.getByRole('region', { name: /items list/i });
    await expect(itemsList).toBeVisible();

    // Get initial stats
    const statsContainer = page.getByRole('region', { name: /stats/i });
    await expect(statsContainer).toBeVisible();

    // Trigger multiple concurrent API calls
    const itemsButton = page.getByRole('button', { name: /load items/i });
    await expect(itemsButton).toBeVisible();
    await itemsButton.click();

    const statsButton = page.getByRole('button', { name: /load stats/i });
    await expect(statsButton).toBeVisible();
    await statsButton.click();

    // Wait for API calls to resolve
    await page.waitForTimeout(500);

    // Verify data is displayed
    const itemsListItems = page.getByText(/item 1/i);
    await expect(itemsListItems).toBeVisible();

    const itemsListCount = page.getByText(/10 items/i);
    await expect(itemsListCount).toBeVisible();

    const statsText = page.getByText(/total revenue: $1000/i);
    await expect(statsText).toBeVisible();

    // Verify stats are displayed
    const statsValue = page.getByText(/total revenue: $1000/i);
    await expect(statsValue).toBeVisible();

    // Verify loading spinner is gone
    const spinner = page.getByRole('status', { name: /loading/i });
    await expect(spinner).not.toBeVisible();
  });

  test('should handle API call failures and display error state', async ({ page }) => {
    // Setup intercepts for API calls
    await page.route('**/api/data/items', (route) => {
      route.abort('failed');
    });
    await page.route('**/api/data/stats', (route) => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ totalRevenue: 1000 })
      });
    });

    // Get initial stats
    const statsContainer = page.getByRole('region', { name: /stats/i });
    await expect(statsContainer).toBeVisible();

    // Trigger concurrent API calls
    const itemsButton = page.getByRole('button', { name: /load items/i });
    await expect(itemsButton).toBeVisible();
    await itemsButton.click();

    const statsButton = page.getByRole('button', { name: /load stats/i });
    await expect(statsButton).toBeVisible();
    await statsButton.click();

    // Wait for API calls to resolve
    await page.waitForTimeout(500);

    // Verify error state is displayed for items
    const errorMessage = page.getByText(/failed to load items/i);
    await expect(errorMessage).toBeVisible();

    // Verify stats are displayed
    const statsText = page.getByText(/total revenue: $1000/i);
    await expect(statsText).toBeVisible();

    // Verify loading spinner is gone
    const spinner = page.getByRole('status', { name: /loading/i });
    await expect(spinner).not.toBeVisible();
  });
});
